#!/usr/bin/python3

def is_valid(f, p, k):
    for i in range(p):
        if f[(k * i) % p] != (k * f[i]) % p:
            return False
    return True

def count_f_arrays(f, p, k, position):
    if position == p:
        return is_valid(f, p, k)
    total = 0
    for val in range(p):
        f.append(val)
        total += count_f_arrays(f, p, k, position + 1)
        f.pop()
    return total

def calculate(p, k):
    group_count = 0
    visited = set()
    for start in range(p):
        if start not in visited:
            group_count += 1
        current = start
        while current not in visited:
            visited.add(current)
            current = (current * k) % p
    return pow(p, group_count - (k != 1), 10 ** 9 + 7)

p, k = map(int, input().split())
print(calculate(p, k))
